对于Python这边，一个简单的多线程TCP服务器：

```python
import socket
import json
import threading
import uuid

HOST = '127.0.0.1'
PORT = 7777

# 状态
instances = {}
signs = {}
conn_to_instance = {}

def send_json(conn, data):
    try:
        msg = json.dumps(data) + '\n'
        conn.sendall(msg.encode('utf-8'))
    except:
        pass

def handle_client(conn, addr):
    print(f"[连接] {addr}")
    buffer = b""
    instance_id = None
    try:
        while True:
            data = conn.recv(4096)
            if not data:
                break
            buffer += data
            while b'\n' in buffer:
                line, buffer = buffer.split(b'\n', 1)
                if line.strip():
                    try:
                        msg = json.loads(line.decode('utf-8'))
                        handle_message(conn, msg, addr)
                    except json.JSONDecodeError as e:
                        print(f"[错误] JSON解析失败: {e}")
    except ConnectionResetError:
        pass
    finally:
        # 清理
        if instance_id:
            # 移除该实例的所有标记
            to_remove = [sid for sid, s in signs.items() if s.get('instance_id') == instance_id]
            for sid in to_remove:
                del signs[sid]
            if instance_id in instances:
                del instances[instance_id]
            print(f"[断开] 实例 {instance_id} 断开，清理 {len(to_remove)} 个标记")
        conn.close()

def handle_message(conn, msg, addr):
    global instance_id_for_conn

    msg_type = msg.get('type')

    if msg_type == 'register_instance':
        instance_id = msg['instance_id']
        instances[instance_id] = {
            'map': msg.get('map', ''),
            'ip': msg.get('ip', ''),
            'port': msg.get('port', 0),
            'conn': conn
        }
        conn_to_instance[conn] = instance_id
        print(f"[实例] {instance_id} 已注册: {msg.get('map', '')}")
        send_json(conn, {'type': 'register_instance_ack', 'success': True})

    elif msg_type == 'unregister_instance':
        instance_id = conn_to_instance.get(conn)
        if instance_id:
            # 清理标记和实例
            to_remove = [sid for sid, s in signs.items() if s.get('instance_id') == instance_id]
            for sid in to_remove:
                del signs[sid]
            if instance_id in instances:
                del instances[instance_id]
            if conn in conn_to_instance:
                del conn_to_instance[conn]
            print(f"[实例] {instance_id} 已注销，清理 {len(to_remove)} 个标记")

    elif msg_type == 'register_sign':
        instance_id = conn_to_instance.get(conn)
        if not instance_id:
            send_json(conn, {'type': 'register_sign_ack', 'success': False, 'error': '未注册实例'})
            return

        sign_id = str(uuid.uuid4())
        sign_data = msg.get('sign_data', {})
        sign_data['sign_id'] = sign_id
        sign_data['instance_id'] = instance_id
        sign_data['time_remaining'] = sign_data.get('time_remaining', 300)
        signs[sign_id] = sign_data
        print(f"[标记] {instance_id} 放置标记 {sign_id}")
        send_json(conn, {'type': 'register_sign_ack', 'sign_id': sign_id, 'success': True})

    elif msg_type == 'unregister_sign':
        sign_id = msg.get('sign_id')
        if sign_id in signs:
            del signs[sign_id]
            print(f"[标记] 移除标记 {sign_id}")

    elif msg_type == 'query_signs':
        instance_id = conn_to_instance.get(conn)
        map_name = msg.get('map', '')
        level = msg.get('level', 0)
        weapon_level = msg.get('weapon_level', 0)

        # 过滤
        results = []
        for sid, s in signs.items():
            if s.get('map') != map_name:
                continue
            if s.get('instance_id') == instance_id:
                continue  # 不返回自己的标记
            if abs(s.get('owner_level', 0) - level) > 10:
                continue
            if abs(s.get('weapon_level', 0) - weapon_level) > 2:
                continue
            results.append(s)

        send_json(conn, {'type': 'query_signs_result', 'signs': results})
        print(f"[查询] {instance_id} 查询到 {len(results)} 个可用标记")

    elif msg_type == 'request_summon':
        sign_id = msg.get('sign_id')
        requester_name = msg.get('requester_name', '')
        requester_instance = msg.get('requester_instance', '')

        if sign_id not in signs:
            send_json(conn, {'type': 'request_summon_ack', 'success': False, 'error': '标记不存在'})
            return

        sign = signs[sign_id]
        owner_instance_id = sign.get('instance_id')

        if owner_instance_id not in instances:
            send_json(conn, {'type': 'request_summon_ack', 'success': False, 'error': '放置者不在线'})
            return

        # 转发给放置者
        owner_conn = instances[owner_instance_id]['conn']
        send_json(owner_conn, {
            'type': 'summon_request',
            'sign_id': sign_id,
            'requester_name': requester_name,
            'requester_instance': requester_instance
        })

        send_json(conn, {'type': 'request_summon_ack', 'success': True})
        print(f"[召唤] {requester_instance}({requester_name}) 请求召唤标记 {sign_id}")

    elif msg_type == 'accept_summon':
        sign_id = msg.get('sign_id')
        if sign_id in signs:
            owner_instance = signs[sign_id].get('instance_id')
            # 通知给所有客户端（标记移除）
            # 具体通知请求者
            # 需要通过request_summon时保存的关系来通知
            # 简化：直接通知请求者
            requester_instance = msg.get('requester_instance')
            if requester_instance in instances:
                requester_conn = instances[requester_instance]['conn']
                send_json(requester_conn, {
                    'type': 'summon_accepted',
                    'sign_id': sign_id,
                    'owner_instance': owner_instance
                })
            # 移除标记
            del signs[sign_id]
            print(f"[召唤] 标记 {sign_id} 被接受")

    elif msg_type == 'decline_summon':
        sign_id = msg.get('sign_id')
        requester_instance = msg.get('requester_instance')
        if requester_instance in instances:
            requester_conn = instances[requester_instance]['conn']
            send_json(requester_conn, {
                'type': 'summon_declined',
                'sign_id': sign_id
            })
        print(f"[召唤] 标记 {sign_id} 被拒绝")

    elif msg_type == 'transfer_phantom_data':
        target_instance = msg.get('target_instance')
        if target_instance in instances:
            target_conn = instances[target_instance]['conn']
            send_json(target_conn, {
                'type': 'phantom_data_received',
                'data': msg.get('data', {})
            })
            print(f"[数据] 灵体数据传输到 {target_instance}")

def start_server():
    server = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    server.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    server.bind((HOST, PORT))
    server.listen(5)
    print(f"[启动] 中间匹配服务已启动 {HOST}:{PORT}")

    while True:
        conn, addr = server.accept()
        thread = threading.Thread(target=handle_client, args=(conn, addr))
        thread.daemon = True
        thread.start()

if __name__ == '__main__':
    start_server()
```

