对于 `PollMessages`，我需要用非阻塞方式：

```cpp
void USL_MatchClientComponent::PollMessages()
{
    if (!MatchSocket || !bIsConnected) return;

    uint32 PendingDataSize = 0;
    while (MatchSocket->HasPendingData(PendingDataSize))
    {
        TArray<uint8> TempBuffer;
        TempBuffer.SetNumUninitialized(PendingDataSize);
        int32 BytesRead = 0;

        if (MatchSocket->Recv(TempBuffer.GetData(), TempBuffer.Num(), BytesRead, ESocketReceiveFlags::None))
        {
            ReceiveBuffer.Append(TempBuffer.GetData(), BytesRead);

            // 逐行解析
            int32 NewLineIndex;
            while (ReceiveBuffer.Find(NewLineIndex, (uint8)'\n'))
            {
                FString Line = UTF8ToString(ReceiveBuffer.GetData(), NewLineIndex);
                ReceiveBuffer.RemoveAt(0, NewLineIndex + 1);

                if (!Line.IsEmpty())
                {
                    ProcessMessage(Line);
                }
            }
        }
        else
        {
            // 连接断开
            bIsConnected = false;
            CleanUpSocket();
            break;
        }
    }
}
```

等等，`ReceiveBuffer.Find` 对TArray<uint8>的查找需要自己实现，或者用标准算法。让我用更简单的方式——用FString累积：

```cpp
FString ReceiveBufferStr;

void PollMessages()
{
    uint32 Size = 0;
    while (MatchSocket && MatchSocket->HasPendingData(Size))
    {
        TArray<uint8> Data;
        Data.AddUninitialized(Size);
        int32 Read = 0;
        MatchSocket->Recv(Data.GetData(), Data.Num(), Read);

        ReceiveBufferStr += FString(UTF8_TO_TCHAR(Data.GetData()));

        int32 NewLineIdx;
        while (ReceiveBufferStr.FindChar('\n', NewLineIdx))
        {
            FString Line = ReceiveBufferStr.Left(NewLineIdx);
            ReceiveBufferStr = ReceiveBufferStr.Mid(NewLineIdx + 1);
            Line.TrimStartAndEndInline();
            if (!Line.IsEmpty()) ProcessMessage(Line);
        }
    }
}
```

对于 `SendMessage`，我用 `FSocket::Send`：

```cpp
void USL_MatchClientComponent::SendMessage(const FString& InJSON)
{
    if (!MatchSocket || !bIsConnected) return;

    FTCHARToUTF8 Converter(*InJSON);
    TArray<uint8> Data;
    Data.Append((uint8*)Converter.Get(), Converter.Length());
    Data.Add((uint8)'\n'); // 分隔符

    int32 BytesSent = 0;
    MatchSocket->Send(Data.GetData(), Data.Num(), BytesSent);
}
```

