```cpp
bool USL_MatchClientComponent::Connect(const FString& InIP, int32 InPort)
{
    SocketSubsystem = ISocketSubsystem::Get(PLATFORM_SOCKETSUBSYSTEM);

    MatchSocket = SocketSubsystem->CreateSocket(NAME_Stream, TEXT("MatchClientSocket"));
    if (!MatchSocket) return false;

    // 设置非阻塞
    MatchSocket->SetBlocking(false);

    // 创建地址
    TSharedRef<FInternetAddr> RemoteAddr = SocketSubsystem->CreateInternetAddr();
    bool bIsValid = false;
    RemoteAddr->SetIp(*InIP, bIsValid);
    RemoteAddr->SetPort(InPort);

    if (!bIsValid) return false;

    // 连接（非阻塞模式）
    double ConnectTimeout = 5.0;
    double StartTime = FPlatformTime::Seconds();
    bool bConnected = false;

    while (FPlatformTime::Seconds() - StartTime < ConnectTimeout)
    {
        if (MatchSocket->Connect(*RemoteAddr))
        {
            bConnected = true;
            break;
        }
        FPlatformProcess::Sleep(0.1f);
    }

    if (!bConnected)
    {
        CleanUpSocket();
        return false;
    }

    bIsConnected = true;

    // 注册Tick
    TickHandle = FTicker::GetCoreTicker().AddTicker(
        FTickerDelegate::CreateRaw(this, &USL_MatchClientComponent::Tick),
        0.05f // 20fps足够了
    );

    return true;
}
```

