+/************************************************************************/
+/*                               外部调用                               */
+/************************************************************************/
+
+bool USL_MatchClientComponent::Connect(const FString& InIP, int32 InPort)
+{
+	if (bIsConnected)
+	{
+		Disconnect();
+	}
+
+	ServerIP = InIP;
+	ServerPort = InPort;
+
+	SocketSubsystem = ISocketSubsystem::Get(PLATFORM_SOCKETSUBSYSTEM);
+	if (!SocketSubsystem)
+	{
+		UE_LOG(LogTemp, Error, TEXT("SL_MatchClientComponent::Connect - Failed to get socket subsystem"));
+		return false;
+	}
+
+	// 创建 TCP Socket
+	MatchSocket = SocketSubsystem->CreateSocket(NAME_Stream, TEXT("MatchClientSocket"), false);
+	if (!MatchSocket)
+	{
+		UE_LOG(LogTemp, Error, TEXT("SL_MatchClientComponent::Connect - Failed to create socket"));
+		return false;
+	}
+
+	// 设置为非阻塞（Tick 轮询用）
+	MatchSocket->SetBlocking(false);
+
+	// 解析远程地址
+	TSharedRef<FInternetAddr> RemoteAddr = SocketSubsystem->CreateInternetAddr();
+	bool bIsValidIP = false;
+	RemoteAddr->SetIp(*InIP, bIsValidIP);
+	RemoteAddr->SetPort(InPort);
+
+	if (!bIsValidIP)
+	{
+		UE_LOG(LogTemp, Error, TEXT("SL_MatchClientComponent::Connect - Invalid IP: %s"), *InIP);
+		CleanUpSocket();
+		return false;
+	}
+
+	// 非阻塞连接：调用 Connect，然后轮询检查是否成功
+	MatchSocket->Connect(*RemoteAddr);
+
+	// 等待连接完成（最多等 3 秒）
+	double StartTime = FPlatformTime::Seconds();
+	double Timeout = 3.0;
+
+	while (FPlatformTime::Seconds() - StartTime < Timeout)
+	{
+		// 检查连接状态：尝试发送空数据看连接是否可用
+		if (MatchSocket->GetConnectionState() == SCS_Connected)
+		{
+			bIsConnected = true;
+			break;
+		}
+
+		// 对于非阻塞 Connect，需要轮询
+		bool bPending = false;
+		if (MatchSocket->HasPendingConnection(bPending) && bPending)
+		{
+			// 连接已完成
+			FPlatformProcess::Sleep(0.05f);
+			continue;
+		}
+
+		FPlatformProcess::Sleep(0.1f);
+	}
+
+	// 再次确认连接状态
+	if (!bIsConnected && MatchSocket->GetConnectionState() == SCS_Connected)
+	{
+		bIsConnected = true;
+	}
+
+	if (!bIsConnected)
+	{
+		UE_LOG(LogTemp, Error, TEXT("SL_MatchClientComponent::Connect - Connection to %s:%d timed out"),
+			*InIP, InPort);
+		CleanUpSocket();
+		return false;
+	}
+
+	// 注册 Tick 轮询接收消息
+	TickHandle = FTicker::GetCoreTicker().AddTicker(
+		FTickerDelegate::CreateRaw(this, &USL_MatchClientComponent::Tick),
+		0.05f  // 20 FPS 足够处理消息
+	);
+
+	UE_LOG(LogTemp, Log, TEXT("SL_MatchClientComponent::Connect - Connected to match server %s:%d"),
+		*InIP, InPort);
+
+	OnConnected.Broadcast(true);
+	return true;
+}
+
+void USL_MatchClientComponent::Disconnect()
+{
+	if (TickHandle.IsValid())
+	{
+		FTicker::GetCoreTicker().RemoveTicker(TickHandle);
+		TickHandle.Reset();
+	}
+
+	// 发送注销消息
+	if (bIsConnected && !InstanceID.IsEmpty())
+	{
+		SendMessage(FString::Printf(
+			TEXT("{\"type\":\"unregister_instance\",\"instance_id\":\"%s\"}"),
+			*InstanceID));
+	}
+
+	CleanUpSocket();
+	bIsConnected = false;
+	InstanceID.Empty();
+	ReceiveBuffer.Empty();
+
+	UE_LOG(LogTemp, Log, TEXT("SL_MatchClientComponent::Disconnect - Disconnected from match server"));
+}
