public class SoulLikeDemo : ModuleRules
{
	public SoulLikeDemo(ReadOnlyTargetRules Target) : base(Target)
	{
		PCHUsage = PCHUsageMode.UseExplicitOrSharedPCHs;

        // 递归获取所有 Public 子目录
