void USL_SignManager::Deinitialize()
{
	// 清理所有标记（同时从中间服务移除）
	TArray<FGuid> AllSigns;
	ActiveSigns.GetKeys(AllSigns);
	for (const FGuid& SignID : AllSigns)
	{
		UnregisterSign(SignID);
	}

	ActiveSigns.Empty();
	OnSignRegistered.Clear();
	OnSignRemoved.Clear();
	OnSignInteracted.Clear();

	Super::Deinitialize();
